<?php
/** In / Out (GAS-CP-R97-182): attendance punches with position.  ?p=inout[&tab=my|today|exc|ot|list|sites|stats|flow]
 *  my — own punches and In / Out from a registered network address; today — who is in; exc — punches waiting for a decision;
 *  ot — overtime beside timesheet and service reports; list — every punch with its map link; sites — known sites and rules;
 *  stats — consistency and accuracy per person (HR, CEO, General Manager only). */
require __DIR__ . '/_layout.php';
$u = require_staff(); $me = (int)$u['id'];
if (!io_has()) { layout_head(t('io.title'), 'inout'); echo '<div class="card"><p class="hint">' . tt('io.need') . '</p></div>'; layout_foot(); return; }
$team = io_team_ids(); $lead = $team === null || $team; $all = $team === null;
$tabs = ['my' => 'io.t_my']; if ($lead) $tabs += ['today' => 'io.t_today', 'exc' => 'io.t_exc', 'ot' => 'io.t_ot', 'list' => 'io.t_list']; if (io_sites_can()) $tabs['sites'] = 'io.t_sites'; if (io_stats_can()) $tabs['stats'] = 'io.t_stats'; $tabs['flow'] = 'io.t_flow';   // R97-189: the process, for everyone
$tab = (string)($_GET['tab'] ?? ($lead ? 'today' : 'my')); if (!isset($tabs[$tab])) $tab = 'my';
$dOk = fn($v, $def) => preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$v) ? (string)$v : $def;
$from = $dOk($_GET['from'] ?? '', date('Y-m-01')); $to = $dOk($_GET['to'] ?? '', date('Y-m-d')); if ($to < $from) $to = $from;
$names = io_staff(); $pend = io_pending_count();
$FL = fn(string $flags) => implode(' ', array_map(fn($f) => pill(in_array($f, ['offday'], true) ? 'gold' : 'bad', t('io.f_' . $f)), array_filter(explode(',', $flags))));
$ST = fn(string $s) => pill(['auto' => 'green', 'approved' => 'green', 'pending' => 'gold', 'rejected' => 'bad'][$s] ?? 'mute', t('io.s_' . $s));
$MAP = fn(array $r) => $r['lat'] === null ? '<span class="hint">' . tt('io.no_pos') . '</span>' : '<a href="' . e(io_map_url((string)$r['lat'], (string)$r['lng'])) . '" target="_blank" rel="noopener noreferrer">📍 ' . tt('io.map') . '</a>';
$WHERE = fn(array $r) => $r['source'] === 'portal' ? e((string)($r['site_name'] ?? '—')) . ' <span class="hint">· ' . tt('io.src_portal') . '</span>' : ($r['site_name'] !== null && $r['dist_m'] !== null ? e((string)$r['site_name']) . ' <span class="hint">· ' . (int)$r['dist_m'] . ' m' . ($r['acc_m'] !== null ? ' (±' . (int)$r['acc_m'] . ' m)' : '') . '</span>' : '<span class="hint">' . ($r['lat'] === null ? '—' : tt('io.no_site')) . '</span>');
$KIND = fn(string $k) => $k === 'in' ? '<b style="color:var(--green,#2E7D32);">▶ ' . tt('io.in') . '</b>' : '<b style="color:var(--navy,#1F3A5F);">■ ' . tt('io.out') . '</b>';
layout_head(t('io.title'), 'inout');
?>
<div class="page-head"><div><h1>⏱ <?= tt('io.title') ?></h1><p class="lede" style="margin-bottom:0;"><?= tt('io.lede') ?></p></div></div>
<div class="tabs"><?php foreach ($tabs as $k => $lk): ?><a class="<?= $tab === $k ? 'on' : '' ?>" href="<?= url('inout', ['tab' => $k]) ?>"><?= tt($lk) ?><?= $k === 'exc' && $pend ? ' <span class="n">' . $pend . '</span>' : '' ?></a><?php endforeach; ?></div>

<?php if ($tab === 'my' && !io_consent_ok($me)): ?>
<div class="card"><div class="card-head"><h2>📄 <?= tt('io.c_title') ?></h2></div><p style="white-space:pre-line;"><?= tt('io.c_text') ?></p>
  <form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="io_consent"><label class="chk"><input type="checkbox" name="agree" value="1" required> <?= tt('io.c_accept') ?></label><div class="btn-row" style="margin-top:10px;"><button class="btn btn--gold" type="submit"><?= tt('io.c_btn') ?></button></div></form></div>
<?php elseif ($tab === 'my'): $st = io_state($me); $cons = io_consent($me); $ip = io_client_ip(); $site = io_site_of_ip($ip); $today = io_day($me, date('Y-m-d')); $mine = io_entries(['user' => $me, 'from' => date('Y-m-d', strtotime('-30 days'))], 200); ?>
<div class="card">
  <div class="card-head"><h2><?= $st['state'] === 'in' ? '🟢 ' . tt('io.you_in') : '⚪ ' . tt('io.you_out') ?></h2><span class="hint"><?= tt('io.today_worked') ?>: <b><?= io_hm($today['net_min']) ?></b><?= $today['sched_min'] ? ' / ' . io_hm($today['sched_min']) : '' ?></span></div>
  <?php if ($site): ?>
    <form method="post" class="btn-row"><?= csrf_field() ?><input type="hidden" name="action" value="io_punch"><input type="hidden" name="kind" value="<?= $st['state'] === 'in' ? 'out' : 'in' ?>">
      <button class="btn btn--gold" type="submit"><?= $st['state'] === 'in' ? '■ ' . tt('io.btn_out') : '▶ ' . tt('io.btn_in') ?></button><span class="hint"><?= tt('io.portal_at', ['site' => (string)$site['name']]) ?></span></form>
  <?php else: ?><p class="hint"><?= tt('io.portal_no', ['ip' => $ip !== '' ? $ip : '—']) ?></p><?php endif; ?>
</div>
<?php if (!empty($cons)): ?><p class="hint">📄 <?= tt('io.c_mine', ['d' => io_fmt_utc($cons['accepted_at'])]) ?></p><?php endif; ?>
<div class="card"><div class="card-head"><h2><?= tt('io.my_last') ?></h2></div>
<?php if (!$mine): ?><p class="hint"><?= tt('io.none') ?></p><?php else: ?><div class="table-scroll"><table class="tbl"><thead><tr><th><?= tt('th.date') ?></th><th><?= tt('io.th_time') ?></th><th></th><th><?= tt('io.th_where') ?></th><th><?= tt('io.th_map') ?></th><th><?= tt('th.status') ?></th></tr></thead><tbody>
<?php foreach ($mine as $r): ?><tr><td><?= e(fmt_date($r['local_day'])) ?></td><td style="font-family:var(--mono);"><?= e(substr((string)$r['local_time'], 0, 5)) ?></td><td><?= $KIND($r['kind']) ?></td><td><?= $WHERE($r) ?></td><td><?= $MAP($r) ?></td><td><?= $ST($r['status']) ?> <?= $FL((string)$r['flags']) ?><?= $r['decide_note'] ? '<br><span class="hint">' . e((string)$r['decide_note']) . '</span>' : '' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>

<?php elseif ($tab === 'today'): $day = $dOk($_GET['day'] ?? '', date('Y-m-d')); $board = io_board($day); if (!$all) $board = array_values(array_filter($board, fn($b) => in_array($b['uid'], $team, true)));
  $nIn = count(array_filter($board, fn($b) => $b['state'] === 'in')); $nOut = count(array_filter($board, fn($b) => $b['state'] === 'out')); $nAbs = count(array_filter($board, fn($b) => $b['state'] === 'absent')); $nNone = count($board) - $nIn - $nOut - $nAbs;
  /* R97-242: filters — state (in · left · absent · no entry · late) and name; the figures stay those of the whole day and are links to the filter */
  $isLate = fn($b) => $b['in'] && in_array('late', array_filter(explode(',', (string)$b['in']['flags'])), true); $nLate = count(array_filter($board, $isLate)); $nAll = count($board);
  $fs = in_array($_GET['state'] ?? '', ['in', 'out', 'absent', 'none', 'late'], true) ? (string)$_GET['state'] : ''; $fq = mb_substr(trim((string)($_GET['q'] ?? '')), 0, 60);
  if ($fs !== '') $board = array_values(array_filter($board, fn($b) => $fs === 'late' ? $isLate($b) : $b['state'] === $fs));
  if ($fq !== '') $board = array_values(array_filter($board, fn($b) => mb_stripos((string)$b['name'], $fq) !== false));
  $tile = fn(string $st) => url('inout', ['tab' => 'today', 'day' => $day, 'state' => $fs === $st ? '' : $st]); ?>
<form method="get" class="btn-row" style="margin:10px 0;"><input type="hidden" name="p" value="inout"><input type="hidden" name="tab" value="today"><input type="date" name="day" value="<?= e($day) ?>">
  <select name="state" data-nosearch title="<?= tt('io.f_state') ?>"><option value=""><?= tt('io.f_all') ?> (<?= $nAll ?>)</option><option value="none"<?= $fs === 'none' ? ' selected' : '' ?>><?= tt('io.k_none') ?> (<?= $nNone ?>)</option><option value="in"<?= $fs === 'in' ? ' selected' : '' ?>><?= tt('io.k_in') ?> (<?= $nIn ?>)</option><option value="out"<?= $fs === 'out' ? ' selected' : '' ?>><?= tt('io.k_out') ?> (<?= $nOut ?>)</option><option value="absent"<?= $fs === 'absent' ? ' selected' : '' ?>><?= tt('io.k_absent') ?> (<?= $nAbs ?>)</option><option value="late"<?= $fs === 'late' ? ' selected' : '' ?>><?= tt('io.f_late') ?> (<?= $nLate ?>)</option></select>
  <input name="q" value="<?= e($fq) ?>" maxlength="60" placeholder="<?= tt('io.f_name') ?>" style="max-width:200px;">
  <button class="btn btn--ghost btn--sm" type="submit"><?= tt('btn.filter') ?></button><?php if ($fs !== '' || $fq !== ''): ?><a class="btn btn--ghost btn--sm" href="<?= url('inout', ['tab' => 'today', 'day' => $day]) ?>"><?= tt('btn.clear') ?></a><span class="hint"><?= e(t('io.f_showing', ['n' => count($board), 'm' => $nAll])) ?></span><?php endif; ?></form>
<div class="kpi kpi--5"><a class="stat<?= $fs === 'in' ? ' gold' : '' ?>" href="<?= $tile('in') ?>"><b><?= $nIn ?></b><span class="s"><?= tt('io.k_in') ?></span></a><a class="stat<?= $fs === 'out' ? ' gold' : '' ?>" href="<?= $tile('out') ?>"><b><?= $nOut ?></b><span class="s"><?= tt('io.k_out') ?></span></a><a class="stat<?= $fs === 'absent' ? ' gold' : '' ?>" href="<?= $tile('absent') ?>" title="<?= tt('io.k_absent_hint') ?>"><b><?= $nAbs ?></b><span class="s"><?= tt('io.k_absent') ?></span></a><a class="stat<?= $fs === 'none' || ($fs === '' && $nNone && $day === date('Y-m-d')) ? ' gold' : '' ?>" href="<?= $tile('none') ?>"><b><?= $nNone ?></b><span class="s"><?= tt('io.k_none') ?></span></a><a class="stat" href="<?= url('inout', ['tab' => 'exc']) ?>"><b><?= $pend ?></b><span class="s"><?= tt('io.k_pend') ?></span></a></div>
<div class="card"><div class="table-scroll"><table class="tbl"><thead><tr><th><?= tt('io.th_person') ?></th><th></th><th><?= tt('io.in') ?></th><th><?= tt('io.th_where') ?></th><th><?= tt('io.out') ?></th><th><?= tt('io.th_where') ?></th></tr></thead><tbody>
<?php if (!$board): ?><tr><td colspan="6" class="hint"><?= tt('io.f_none') ?></td></tr><?php endif; ?>
<?php foreach ($board as $b): $i = $b['in']; $o = $b['out']; ?><tr><td><a href="<?= url('inout', ['tab' => 'list', 'user' => $b['uid'], 'from' => $day, 'to' => $day]) ?>"><?= e($b['name']) ?></a></td><td><?= pill($b['state'] === 'in' ? 'green' : ($b['state'] === 'out' ? 'mute' : ($b['state'] === 'absent' ? 'navy' : 'gold')), t('io.st_' . $b['state'])) ?></td>
  <td style="font-family:var(--mono);"><?= $i ? e(substr((string)$i['local_time'], 0, 5)) . ' ' . $FL((string)$i['flags']) : '—' ?></td><td><?= $i ? $WHERE($i) . ' ' . $MAP($i) : '' ?></td>
  <td style="font-family:var(--mono);"><?= $o ? e(substr((string)$o['local_time'], 0, 5)) . ' ' . $FL((string)$o['flags']) : '—' ?></td><td><?= $o ? $WHERE($o) . ' ' . $MAP($o) : '' ?></td></tr><?php endforeach; ?></tbody></table></div></div>

<?php elseif ($tab === 'exc'): $rows = io_entries(['status' => 'pending'] + ($all ? [] : ['users' => $team]), 300); ?>
<div class="card"><p class="hint"><?= tt('io.exc_lede', ['n' => io_tol()]) ?></p>
<?php if (!$rows): ?><p class="hint"><?= tt('io.exc_none') ?></p><?php else: ?>
<form method="post" id="io-all"><?= csrf_field() ?><input type="hidden" name="action" value="io_decide_all">
<div class="table-scroll"><table class="tbl"><thead><tr><th></th><th><?= tt('io.th_person') ?></th><th><?= tt('th.date') ?></th><th><?= tt('io.th_time') ?></th><th></th><th><?= tt('io.th_why') ?></th><th><?= tt('io.th_where') ?></th><th><?= tt('io.th_map') ?></th><th><?= tt('io.th_booked') ?></th></tr></thead><tbody>
<?php foreach ($rows as $r): $bk = io_booked((int)$r['user_id'], (string)$r['local_day']); ?><tr><td><input type="checkbox" name="ids[]" value="<?= (int)$r['id'] ?>" aria-label="<?= e($r['full_name']) ?>"></td><td><?= e($r['full_name']) ?></td><td><?= e(fmt_date($r['local_day'])) ?></td><td style="font-family:var(--mono);"><?= e(substr((string)$r['local_time'], 0, 5)) ?><?= $r['late_sync'] ? ' <span class="hint" title="' . tt('io.late_sync') . '">⏳</span>' : '' ?></td><td><?= $KIND($r['kind']) ?></td><td><?= $FL((string)$r['flags']) ?></td><td><?= $WHERE($r) ?></td><td><?= $MAP($r) ?></td>
  <td class="hint"><?= tt('io.ts') ?> <?= $bk['ts'] === null ? '—' : rtrim(rtrim(number_format($bk['ts'], 2, '.', ''), '0'), '.') . ' h' ?> · <?= tt('io.fsr') ?> <?= $bk['fsr'] === null ? '—' : rtrim(rtrim(number_format($bk['fsr'], 2, '.', ''), '0'), '.') . ' h' ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="btn-row" style="margin-top:10px;"><input type="text" name="note" maxlength="300" placeholder="<?= tt('io.note_ph') ?>" style="max-width:340px;"><button class="btn btn--gold" type="submit" name="status" value="approved">✓ <?= tt('hr.approve') ?></button><button class="btn btn--ghost" type="submit" name="status" value="rejected">✕ <?= tt('hr.reject') ?></button><span class="hint"><?= tt('io.sel_hint') ?></span></div></form>
<?php endif; ?></div>

<?php elseif ($tab === 'ot'): $rows = io_overtime_days($from, $to, $all ? null : $team); ?>
