<?php foreach ($rows as $x): $s = $x['s']; $bk = $s['booked']; $h = fn($v) => $v === null ? '—' : rtrim(rtrim(number_format((float)$v, 2, '.', ''), '0'), '.') . ' h'; ?><tr>
  <td><a href="<?= url('inout', ['tab' => 'list', 'user' => $x['uid'], 'from' => $x['day'], 'to' => $x['day']]) ?>"><?= e($x['name']) ?></a></td><td><?= e(fmt_date($x['day'])) ?><?= $s['workday'] ? '' : ' ' . pill('gold', t('io.f_offday')) ?></td>
  <td style="font-family:var(--mono);"><?= $s['first'] ? e(substr((string)$s['first']['local_time'], 0, 5)) : '—' ?> – <?= $s['open'] ? '<span class="hint">' . tt('io.open') . '</span>' : ($s['last'] ? e(substr((string)$s['last']['local_time'], 0, 5)) : '—') ?></td>
  <td><?= io_hm($s['net_min']) ?></td><td><?= io_hm($s['sched_min']) ?></td><td><b><?= $s['ot_min'] ? io_hm($s['ot_min']) : '—' ?></b></td>
  <td><?= $h($bk['ts']) ?><?= $bk['ts'] !== null && $bk['ts_ot'] > 0 ? ' <span class="hint">(' . tt('io.ot_short') . ' ' . $h($bk['ts_ot']) . ')</span>' : '' ?><?= in_array('ts', $s['mismatch'], true) ? ' ' . pill('bad', t('io.mismatch')) : '' ?></td>
  <td><?= $h($bk['fsr']) ?><?= in_array('fsr', $s['mismatch'], true) ? ' ' . pill('bad', t('io.mismatch')) : '' ?></td>
