  <td class="row-actions"><?php if ($s['ot_min'] && !$s['open'] && io_can_decide($x['uid'])): ?><form method="post" class="btn-row"><?= csrf_field() ?><input type="hidden" name="action" value="io_ot_decide"><input type="hidden" name="uid" value="<?= $x['uid'] ?>"><input type="hidden" name="day" value="<?= e($x['day']) ?>"><input type="hidden" name="from" value="<?= e($from) ?>"><input type="hidden" name="to" value="<?= e($to) ?>"><input type="text" name="note" maxlength="300" placeholder="<?= tt('io.note_ph') ?>" style="width:130px;"><button class="btn btn--gold btn--sm" name="status" value="approved" type="submit">✓</button><button class="btn btn--ghost btn--sm" name="status" value="rejected" type="submit">✕</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>

<?php elseif ($tab === 'list'): $fu = (int)($_GET['user'] ?? 0); if (!$all && $fu && !in_array($fu, $team, true)) $fu = 0; $rows = io_entries(['from' => $from, 'to' => $to] + ($fu ? ['user' => $fu] : ($all ? [] : ['users' => $team])), 800); ?>
<form method="get" class="btn-row" style="margin:10px 0;"><input type="hidden" name="p" value="inout"><input type="hidden" name="tab" value="list"><select name="user"><option value="0"><?= tt('io.everyone') ?></option><?php foreach ($names as $id => $n): if (!$all && !in_array($id, $team, true)) continue; ?><option value="<?= $id ?>" <?= $fu === $id ? 'selected' : '' ?>><?= e($n) ?></option><?php endforeach; ?></select><label><?= tt('th.from') ?> <input type="date" name="from" value="<?= e($from) ?>"></label><label><?= tt('th.to') ?> <input type="date" name="to" value="<?= e($to) ?>"></label><button class="btn btn--ghost btn--sm" type="submit"><?= tt('btn.filter') ?></button></form>
<div class="card"><?php if (!$rows): ?><p class="hint"><?= tt('io.none') ?></p><?php else: ?><div class="table-scroll"><table class="tbl"><thead><tr><th><?= tt('io.th_person') ?></th><th><?= tt('th.date') ?></th><th><?= tt('io.th_time') ?></th><th></th><th><?= tt('io.th_where') ?></th><th><?= tt('io.th_map') ?></th><th><?= tt('io.th_src') ?></th><th><?= tt('th.status') ?></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['full_name']) ?></td><td><?= e(fmt_date($r['local_day'])) ?></td><td style="font-family:var(--mono);"><?= e(substr((string)$r['local_time'], 0, 5)) ?><?= $r['late_sync'] ? ' <span class="hint" title="' . tt('io.late_sync') . '">⏳</span>' : '' ?></td><td><?= $KIND($r['kind']) ?></td><td><?= $WHERE($r) ?></td><td><?= $MAP($r) ?><?= $r['lat'] !== null ? '<br><span class="hint" style="font-family:var(--mono);">' . e(number_format((float)$r['lat'], 5, '.', '') . ', ' . number_format((float)$r['lng'], 5, '.', '')) . '</span>' : '' ?></td><td class="hint"><?= e(t('io.src_' . (in_array($r['source'], ['portal', 'employee', 'engineer', 'pm', 'hr'], true) ? $r['source'] : 'portal'))) ?><?= $r['source'] === 'portal' && $r['ip'] ? '<br>' . e((string)$r['ip']) : '' ?></td>
  <td><?= $ST($r['status']) ?> <?= $FL((string)$r['flags']) ?><?= $r['decided_name'] ? '<br><span class="hint">' . e((string)$r['decided_name']) . ($r['decide_note'] ? ' · ' . e((string)$r['decide_note']) : '') . '</span>' : '' ?></td></tr><?php endforeach; ?></tbody></table></div><p class="hint"><?= tt('io.list_foot', ['n' => count($rows)]) ?></p><?php endif; ?></div>

