<form method="post" id="site-form" class="form-grid" style="margin-top:14px;"><?= csrf_field() ?><input type="hidden" name="action" value="io_site_save"><input type="hidden" name="id" value="<?= $cur ? (int)$cur['id'] : 0 ?>">
  <label><?= tt('io.site_name') ?><input type="text" name="name" maxlength="120" required value="<?= e((string)($cur['name'] ?? '')) ?>"></label>
  <label><?= tt('io.site_pos') ?><input type="text" name="pos" required placeholder="37.94321, 23.61234" value="<?= $cur ? e(number_format((float)$cur['lat'], 6, '.', '') . ', ' . number_format((float)$cur['lng'], 6, '.', '')) : '' ?>"><span class="hint"><?= tt('io.site_pos_hint') ?></span></label>
  <label><?= tt('io.site_radius') ?> (m)<input type="number" name="radius_m" min="30" max="20000" value="<?= (int)($cur['radius_m'] ?? 300) ?>"></label>
  <label><?= tt('io.site_ips') ?><input type="text" name="ips" maxlength="400" placeholder="203.0.113.25, 198.51.100.*" value="<?= e((string)($cur['ips'] ?? '')) ?>"><span class="hint"><?= tt('io.site_ips_hint', ['ip' => io_client_ip() !== '' ? io_client_ip() : '—']) ?></span></label>
  <label class="chk"><input type="checkbox" name="is_active" value="1" <?= !$cur || $cur['is_active'] ? 'checked' : '' ?>> <?= tt('io.active') ?></label>
  <div class="btn-row"><button class="btn btn--gold" type="submit"><?= $cur ? tt('btn.save') : tt('io.site_add') ?></button><?php if ($cur): ?><a class="btn btn--ghost" href="<?= url('inout', ['tab' => 'sites']) ?>"><?= tt('io.cancel') ?></a><?php endif; ?></div></form></div>
<?php $ca = io_consents_all(); $miss = array_diff_key($names, $ca); ?>
<div class="card"><div class="card-head"><h2>📄 <?= tt('io.c_list') ?></h2><span class="hint"><?= tt('io.c_count', ['n' => count(array_intersect_key($ca, $names)), 'm' => count($names)]) ?></span></div><p class="hint"><?= tt('io.c_list_lede') ?></p>
<?php if ($ca): ?><div class="table-scroll"><table class="tbl"><thead><tr><th><?= tt('io.th_person') ?></th><th><?= tt('io.c_when') ?></th><th><?= tt('io.th_src') ?></th></tr></thead><tbody><?php foreach ($ca as $uid => $c): ?><tr><td><?= e($names[$uid] ?? ('#' . $uid)) ?></td><td><?= e(io_fmt_utc($c['accepted_at'])) ?></td><td class="hint"><?= e(t('io.src_' . (in_array($c['source'], ['portal', 'employee', 'engineer', 'pm', 'hr'], true) ? $c['source'] : 'portal'))) ?><?= $c['ip'] ? ' · ' . e((string)$c['ip']) : '' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if ($miss): ?><p class="hint" style="margin-top:8px;"><b><?= tt('io.c_missing') ?>:</b> <?= e(implode(', ', $miss)) ?></p><?php endif; ?></div>
<div class="card"><div class="card-head"><h2>⚙ <?= tt('io.rules') ?></h2></div><p class="hint"><?= tt('io.rules_lede') ?></p>
<form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="io_settings_save">
  <label><?= tt('io.r_tol') ?><input type="number" name="io_tolerance_min" min="0" max="120" value="<?= io_tol() ?>"></label>
  <label><?= tt('io.r_weak') ?><input type="number" name="io_weak_gps_m" min="20" max="5000" value="<?= io_weak() ?>"></label>
  <label><?= tt('io.r_ot') ?><input type="number" name="io_ot_min" min="0" max="240" value="<?= io_ot_min() ?>"></label>
  <label><?= tt('io.r_diff') ?><input type="number" name="io_diff_min" min="0" max="240" value="<?= io_diff_min() ?>"></label>
  <label><?= tt('io.r_ev') ?><input type="number" name="io_ev_ok" min="50" max="100" value="<?= io_ev_ok() ?>"></label>
  <div class="btn-row"><button class="btn btn--gold" type="submit"><?= tt('btn.save') ?></button></div></form></div>

<?php elseif ($tab === 'stats'): $rows = io_stats($from, $to); $pc = fn($v) => $v === null ? '—' : $v . ' %'; ?>
<form method="get" class="btn-row" style="margin:10px 0;"><input type="hidden" name="p" value="inout"><input type="hidden" name="tab" value="stats"><label><?= tt('th.from') ?> <input type="date" name="from" value="<?= e($from) ?>"></label><label><?= tt('th.to') ?> <input type="date" name="to" value="<?= e($to) ?>"></label><button class="btn btn--ghost btn--sm" type="submit"><?= tt('btn.filter') ?></button></form>
<div class="card"><p class="hint">🔒 <?= tt('io.stats_lede') ?></p>
<?php if (!$rows): ?><p class="hint"><?= tt('io.none') ?></p><?php else: ?><div class="table-scroll"><table class="tbl"><thead><tr><th><?= tt('io.th_person') ?></th><th><?= tt('io.st_days') ?></th><th><?= tt('io.st_cons') ?></th><th><?= tt('io.st_acc') ?></th><th><?= tt('io.st_punct') ?></th><th><?= tt('io.st_late') ?></th><th><?= tt('io.f_outside') ?></th><th><?= tt('io.f_early') ?></th><th><?= tt('io.st_noout') ?></th><th><?= tt('io.st_rej') ?></th><th><?= tt('io.st_ot') ?></th></tr></thead><tbody>
<?php foreach ($rows as $r): $tone = fn($v) => $v === null ? 'mute' : ($v >= 90 ? 'green' : ($v >= 70 ? 'gold' : 'bad')); ?><tr><td><a href="<?= url('inout', ['tab' => 'list', 'user' => $r['uid'], 'from' => $from, 'to' => $to]) ?>"><?= e($r['name']) ?></a></td><td><?= $r['present'] ?> / <?= $r['workdays'] ?></td><td><?= pill($tone($r['consistency']), $pc($r['consistency'])) ?></td><td><?= pill($tone($r['accuracy']), $pc($r['accuracy'])) ?></td><td><?= pill($tone($r['punctual']), $pc($r['punctual'])) ?></td>
  <td><?= $r['flags']['late'] ?><?= $r['late_avg'] ? ' <span class="hint">(⌀ ' . $r['late_avg'] . ' min)</span>' : '' ?></td><td><?= $r['flags']['outside'] ?></td><td><?= $r['flags']['early'] ?></td><td><?= max(0, $r['present'] - $r['complete']) ?></td><td><?= $r['rejected'] ?></td><td><?= io_hm($r['ot_ok']) ?><?= $r['ot_no'] ? ' <span class="hint">(✕ ' . io_hm($r['ot_no']) . ')</span>' : '' ?></td></tr><?php endforeach; ?></tbody></table></div><p class="hint"><?= tt('io.stats_foot') ?></p><?php endif; ?></div>
<?php endif; ?>
<?php if ($tab === 'flow') require __DIR__ . '/_inout_flow.php'; ?>
